catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading) {
      return;
   }

   //Type appropriate comment here, and begin script below

    var ga = new GlideAjax("x_hccc_hoc_ohs.HoCOHSMUtils");
    ga.addParam("sysparm_name", "getParentOHSMDetails");
    ga.addParam("sysparm_task_num", newValue);
    ga.getXMLAnswer(getParentDetails);


    function getParentDetails(response) {
        var result = JSON.parse(response); //transform the JSON string to an object		
		var hazardous_situation = "";
		if (result.sc_hazardous_situation == "true"  || result.sc_hazardous_situation == "vrai"){hazardous_situation = getMessage("Yes");}else{hazardous_situation = getMessage("No");}

		var danger_exists = "";
		if (result.danger_exists == "yes" || result.danger_exists == "oui"){danger_exists = getMessage("Yes");}else{danger_exists = getMessage("No");}

		g_form.setValue("inc_date_time", result.inc_date_time);
        g_form.setValue("inc_location", result.inc_location);
        g_form.setValue("sc_hazardous_situation", hazardous_situation);
        g_form.setValue("hazard_type", result.hazard_type);
        g_form.setValue("danger_exists", danger_exists);
        g_form.setValue("sc_action_plan", result.sc_action_plan);
		g_form.setValue('rw_whsc_decision',result.rw_whsc_decision);
		g_form.setValue('whsc_comments',result.whsc_comments);
		g_form.setValue('minister_of_labour_decision',result.rw_minister_of_labour_decision);
		g_form.setValue('minister_of_labour_recommendations',result.rw_minister_of_labour_recommendations);
    }
}
